            { label: 'ดอกเบี้ย / ผลตอบแทนสะสม', value: `+${formatMoney(interestEarned)} บาท`, highlight: true },
            { label: 'มูลค่าที่แท้จริงหลังหักเงินเฟ้อ', value: `${formatMoney(realValue)} บาท` }
