function getToolFieldBindings(toolId) {
    switch (toolId) {
        case 'unit_price': {
            const list = [];
            appState.unit_price.rows.forEach((row, idx) => {
                list.push({
                    get: () => appState.unit_price.rows[idx].price,
                    set: (v) => { appState.unit_price.rows[idx].price = v; }
                });
                list.push({
                    get: () => appState.unit_price.rows[idx].qty,
                    set: (v) => { appState.unit_price.rows[idx].qty = v; }
                });
            });
            return list;
        }
        case 'currency':
            return [
                { get: () => appState.currency.amount, set: (v) => { appState.currency.amount = v; } },
                { get: () => appState.currency.customRateToTHB, set: (v) => { appState.currency.customRateToTHB = v; } }
            ];
        case 'unit':
            return [
                { get: () => appState.unit.val, set: (v) => { appState.unit.val = v; } }
            ];
        case 'construction_calc': {
            const st = appState.construction_calc || {};
            const tab = st.tab || 'tiles';
            if (tab === 'tiles') {
                return [
                    { get: () => (appState.construction_calc ? appState.construction_calc.tileWidth : ''), set: (v) => { if (appState.construction_calc) appState.construction_calc.tileWidth = v; } },
                    { get: () => (appState.construction_calc ? appState.construction_calc.tileLength : ''), set: (v) => { if (appState.construction_calc) appState.construction_calc.tileLength = v; } },
                    { get: () => (appState.construction_calc ? appState.construction_calc.tilePricePerBox : ''), set: (v) => { if (appState.construction_calc) appState.construction_calc.tilePricePerBox = v; } }
                ];
            } else if (tab === 'paint') {
                return [
                    { get: () => (appState.construction_calc ? appState.construction_calc.paintWallWidth : ''), set: (v) => { if (appState.construction_calc) appState.construction_calc.paintWallWidth = v; } },
                    { get: () => (appState.construction_calc ? appState.construction_calc.paintWallHeight : ''), set: (v) => { if (appState.construction_calc) appState.construction_calc.paintWallHeight = v; } },
                    { get: () => (appState.construction_calc ? appState.construction_calc.paintDeductArea : ''), set: (v) => { if (appState.construction_calc) appState.construction_calc.paintDeductArea = v; } }
                ];
            } else {
                return [
                    { get: () => (appState.construction_calc ? appState.construction_calc.slabWidth : ''), set: (v) => { if (appState.construction_calc) appState.construction_calc.slabWidth = v; } },
                    { get: () => (appState.construction_calc ? appState.construction_calc.slabLength : ''), set: (v) => { if (appState.construction_calc) appState.construction_calc.slabLength = v; } },
                    { get: () => (appState.construction_calc ? appState.construction_calc.slabThickness : ''), set: (v) => { if (appState.construction_calc) appState.construction_calc.slabThickness = v; } }
                ];
            }
        }
        case 'discount':
            return [
                { get: () => appState.discount.price, set: (v) => { appState.discount.price = v; } },
                { get: () => appState.discount.discountPct, set: (v) => { appState.discount.discountPct = v; } },
                { get: () => appState.discount.extraPct, set: (v) => { appState.discount.extraPct = v; } }
            ];
        case 'percent':
            return [
                { get: () => appState.percent.x, set: (v) => { appState.percent.x = v; } },
                { get: () => appState.percent.y, set: (v) => { appState.percent.y = v; } },
                { get: () => appState.percent.z, set: (v) => { appState.percent.z = v; } }
            ];
        case 'vat':
            return [
                { get: () => appState.vat.amount, set: (v) => { appState.vat.amount = v; } },
                { get: () => appState.vat.rate, set: (v) => { appState.vat.rate = v; } }
            ];
        case 'fuel_cost':
            if (appState.fuel_cost && appState.fuel_cost.mode === 'ev') {
                return [
                    { get: () => appState.fuel_cost.distance, set: (v) => { appState.fuel_cost.distance = v; } },
                    { get: () => appState.fuel_cost.evEfficiency, set: (v) => { appState.fuel_cost.evEfficiency = v; } },
                    { get: () => appState.fuel_cost.electricityRate, set: (v) => { appState.fuel_cost.electricityRate = v; } }
                ];
            }
            return [
                { get: () => appState.fuel_cost.distance, set: (v) => { appState.fuel_cost.distance = v; } },
                { get: () => appState.fuel_cost.efficiency, set: (v) => { appState.fuel_cost.efficiency = v; } },
                { get: () => appState.fuel_cost.oilPrice, set: (v) => { appState.fuel_cost.oilPrice = v; } }
            ];
        case 'health':
            return [
                { get: () => appState.health.weight, set: (v) => { appState.health.weight = v; } },
                { get: () => appState.health.height, set: (v) => { appState.health.height = v; } },
                { get: () => appState.health.age, set: (v) => { appState.health.age = v; } }
            ];
        case 'tip':
            return [
                { get: () => appState.tip.bill, set: (v) => { appState.tip.bill = v; } },
                { get: () => appState.tip.tipPct, set: (v) => { appState.tip.tipPct = v; } },
                { get: () => appState.tip.people, set: (v) => { appState.tip.people = v; } }
            ];
        case 'btu_calc':
            return [
                { get: () => appState.btu_calc.width, set: (v) => { appState.btu_calc.width = v; } },
                { get: () => appState.btu_calc.length, set: (v) => { appState.btu_calc.length = v; } },
                { get: () => appState.btu_calc.height, set: (v) => { appState.btu_calc.height = v; } },
                { get: () => appState.btu_calc.btuPerSqm, set: (v) => { appState.btu_calc.btuPerSqm = v; } },
                { get: () => appState.btu_calc.hoursPerDay, set: (v) => { appState.btu_calc.hoursPerDay = v; } },
                { get: () => appState.btu_calc.ratePerKwh, set: (v) => { appState.btu_calc.ratePerKwh = v; } }
            ];
        case 'fuel_eff':
            return [
                { get: () => appState.fuel_eff.distance, set: (v) => { appState.fuel_eff.distance = v; } },
                { get: () => appState.fuel_eff.fuelUsed, set: (v) => { appState.fuel_eff.fuelUsed = v; } }
            ];
        case 'loan':
            return [
                { get: () => appState.loan.principal, set: (v) => { appState.loan.principal = v; } },
                { get: () => appState.loan.interestRate, set: (v) => { appState.loan.interestRate = v; } },
                { get: () => appState.loan.months, set: (v) => { appState.loan.months = v; } },
                { get: () => appState.loan.extra, set: (v) => { appState.loan.extra = v; } }
            ];
        case 'savings':
            return [
                { get: () => appState.savings.initial, set: (v) => { appState.savings.initial = v; } },
                { get: () => appState.savings.monthly, set: (v) => { appState.savings.monthly = v; } },
                { get: () => appState.savings.interestRate, set: (v) => { appState.savings.interestRate = v; } },
                { get: () => appState.savings.years, set: (v) => { appState.savings.years = v; } }
            ].slice(0, appState.savings.mode === 'retirement' ? 3 : 4);
        case 'salary':
            return [
                {
                    get: () => (appState.salary.mode === 'net' ? (appState.salary.baseSalary !== undefined ? appState.salary.baseSalary : appState.salary.income) : appState.salary.income),
                    set: (v) => {
                        if (appState.salary.mode === 'net') {
                            appState.salary.baseSalary = v;
                        } else {
                            appState.salary.income = v;
                        }
                    }
                },
                { get: () => appState.salary.needsPct, set: (v) => { appState.salary.needsPct = v; } },
                { get: () => appState.salary.wantsPct, set: (v) => { appState.salary.wantsPct = v; } },
                { get: () => appState.salary.savingsPct, set: (v) => { appState.salary.savingsPct = v; } }
            ];
        default:
            return [];
    }
}

function handleSharedKeyInput(key) {
    const inputs = [...document.querySelectorAll('#toolTopPanel input[data-shared-field]')];
    if (!inputs.length) return;
    const input = inputs.find(field => Number(field.dataset.sharedField) === appState.activeFieldIndex) || inputs[0];
    const clearSnapshot = key === 'CLEAR' ? captureToolSnapshot() : null;
    if (key === 'PREV' || key === 'NEXT') {
        const direction = key === 'NEXT' ? 1 : -1;
        inputs[(inputs.indexOf(input) + direction + inputs.length) % inputs.length].focus();
        return;
    }
    const selection = input.dataset.visited ? [input.selectionStart, input.selectionEnd] : [input.value.length, input.value.length];
    input.focus();
    input.setSelectionRange(...selection);
    let start = input.selectionStart, end = input.selectionEnd;
    if (key === 'CLEAR') {
        start = 0; end = input.value.length;
    } else if (key === 'BACKSPACE' && start === end) {
        if (start > 1 && input.value[start - 1] === ',') {
            start = Math.max(0, start - 2);
        } else {
            start = Math.max(0, start - 1);
        }
    }
    const replacement = key === 'CLEAR' || key === 'BACKSPACE' ? '' : key;
    if (!/^(?:CLEAR|BACKSPACE|[0-9.]|00)$/.test(key)) return;
    input.setRangeText(replacement, start, end, 'end');
    input.dispatchEvent(new Event('input', { bubbles: true }));
    if (clearSnapshot) rememberToolClear(clearSnapshot);
}

function updateKeypadCollapseUI(collapsed) {
    if (typeof document === 'undefined') return;
    const keypad = document.getElementById('sharedKeypadSection');
    const icon = document.getElementById('toggleKeypadIcon');
    const label = document.getElementById('toggleKeypadLabel');
    const toggle = document.getElementById('toggleKeypadBtn');
    toggle?.setAttribute('aria-expanded', String(!collapsed));
    toggle?.setAttribute('aria-controls', 'sharedKeypadSection');
    toggle?.setAttribute('aria-label', collapsed ? 'แสดงแป้นตัวเลข' : 'ซ่อนแป้นตัวเลข');
    toggle?.setAttribute('title', collapsed ? 'แสดงแป้นตัวเลข' : 'ซ่อนแป้นตัวเลข');
    if (collapsed) {
        keypad?.classList.add('keypad-collapsed');
        icon?.classList.add('rotate-180');
        if (label) label.textContent = 'ขยาย';
    } else {
        keypad?.classList.remove('keypad-collapsed');
        icon?.classList.remove('rotate-180');
        if (label) label.textContent = 'ย่อ';
    }
}

// Keypad & Keyboard Event Listeners Initialization
function initKeypadListeners() {
    if (typeof document === "undefined" || typeof document.querySelectorAll !== "function") return;
    document.querySelectorAll("#sharedKeypadSection .key-btn").forEach(btn => {
        btn.addEventListener("mousedown", event => event.preventDefault());
        btn.addEventListener("click", () => {
            const key = btn.getAttribute("data-key");
            handleSharedKeyInput(key);
        });
    });

    document.getElementById("toggleKeypadBtn")?.addEventListener("click", (e) => {
        e.stopPropagation();
        const keypad = document.getElementById("sharedKeypadSection");
        const isNowCollapsed = !keypad?.classList.contains("keypad-collapsed");
        updateKeypadCollapseUI(isNowCollapsed);
    });

    // Only fields wired to the shared keypad may open it. Native numeric
    // controls keep their own editor, so keys cannot change another field.
    const panel = document.getElementById('toolTopPanel');
    const sharedField = '#toolTopPanel input[data-shared-field]:not(:disabled):not([readonly])';
    const keypadControls = '#sharedKeypadSection, #keypadToolbar';
    panel?.addEventListener('focusin', event => {
        updateKeypadCollapseUI(!event.target.matches(sharedField));
    });
    panel?.addEventListener('focusout', () => {
        // Renderers replace focused fields synchronously and then restore focus.
        queueMicrotask(() => {
            if (!document.activeElement?.matches(sharedField) &&
                !document.activeElement?.closest(keypadControls)) updateKeypadCollapseUI(true);
        });
    });
    document.addEventListener('pointerdown', event => {
        const target = event.target;
        if (!target?.closest) return;
        if (target.closest(keypadControls)) return;
        // Unit selects and wheel-popover buttons are pickers; the in-app keypad must not open for them.
        if (target.closest('select, .unit-wheel-trigger, .unit-wheel-popover')) { updateKeypadCollapseUI(true); return; }
        const field = target.matches(sharedField) ? target : target.closest('#toolTopPanel [data-field-index]')?.querySelector('input[data-shared-field]:not(:disabled):not([readonly])');
        if (field) {
            updateKeypadCollapseUI(false);
            return;
        }
        updateKeypadCollapseUI(true);
        if (document.activeElement?.matches(sharedField)) document.activeElement.blur();
    });

    if (typeof window !== "undefined") {
        window.addEventListener("keydown", (e) => {
            const toolMeta = typeof TOOLS_CATALOG !== "undefined" ? TOOLS_CATALOG.find(t => t.id === appState.activeToolId) : null;
            if (!toolMeta) return;
            if (e.target?.matches?.("input, select, textarea, [contenteditable=\"true\"]")) {
                if (e.key === "Escape") { e.preventDefault(); e.target.blur(); }
                return;
            }
            // Let Enter and Space activate the focused control normally.
            if ((e.key === "Enter" || e.key === " ") && e.target?.closest?.('button, a, [role="button"]')) return;
            if (appState.activeToolId === "calc" && !["INPUT", "SELECT", "TEXTAREA"].includes(document.activeElement?.tagName)) {
                const stdKey = e.key === "*" ? "×" : e.key === "/" ? "÷" : e.key === "Enter" ? "=" : e.key === "Backspace" ? "BS" : e.key === "Escape" ? "C" : e.key;
                const stdButton = document.querySelector(`#toolTopPanel [data-std="${CSS.escape(stdKey)}"]`);
                if (stdButton) { e.preventDefault(); stdButton.click(); }
                return;
            }
            if (e.key === "Escape") { e.preventDefault(); updateKeypadCollapseUI(true); return; }
            if (!toolMeta.usesSharedKeypad) return;
            if (["INPUT", "SELECT", "TEXTAREA"].includes(document.activeElement?.tagName)) return;
            if (e.target?.closest?.("button, a, [role=\"button\"]")) return;
            if (e.key >= "0" && e.key <= "9") {
                e.preventDefault();
                handleSharedKeyInput(e.key);
            } else if (e.key === ".") {
                e.preventDefault();
                handleSharedKeyInput(".");
            } else if (e.key === "Backspace") {
                e.preventDefault();
                handleSharedKeyInput("BACKSPACE");
            } else if (e.key === "Escape" || e.key === "Delete") {
                e.preventDefault();
                handleSharedKeyInput("CLEAR");
            }
        });
    }
}

if (typeof document !== "undefined") {
    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", initKeypadListeners);
    } else {
        initKeypadListeners();
    }
}

/**************************************************************
 * 6. HELPER TO CREATE INTERACTIVE FIELD ROW FOR SHARED KEYPAD
 **************************************************************/
function createKeypadFieldHTML(fieldIndex, label, value, unitSuffix = '', placeholder = '0') {
    const isActive = appState.activeFieldIndex === fieldIndex;
    const clean = normalizeThaiDigits(String(value ?? '')).trim().replace(/,/g, '');
    const isIntermediate = clean === '' || clean === '.' || clean === '-' || clean === '-.';
    const invalid = !isIntermediate && !Number.isFinite(parseNumericInput(clean));
    const displayVal = formatInputDisplay(value);
    // Touch devices use the in-app keypad only; PC keeps the native keyboard.
    const sharedInputMode = window.matchMedia('(pointer: coarse)').matches ? 'none' : 'decimal';
    return `<div><div class="clev-field-box ${isActive ? 'active-field' : ''}" data-field-index="${fieldIndex}">
        <label for="numeric-field-${fieldIndex}" class="text-sm font-medium text-[var(--app-ink)]">${label}</label>
        <div class="flex items-center gap-1.5 min-w-0" style="max-width:55%">
            <input id="numeric-field-${fieldIndex}" data-shared-field="${fieldIndex}" type="text" inputmode="${sharedInputMode}" autocomplete="off" spellcheck="false" class="shared-number-input" aria-invalid="${invalid}" ${invalid ? `aria-describedby="numeric-error-${fieldIndex}"` : ''} value="${escapeHTML(displayVal)}" placeholder="${escapeHTML(placeholder)}">
            ${unitSuffix ? `<span class="text-xs font-medium text-[var(--app-muted)]">${unitSuffix}</span>` : ''}
        </div>
    </div>${invalid ? `<p id="numeric-error-${fieldIndex}" role="alert" class="text-xs px-3 py-1">กรุณากรอกตัวเลข เช่น 1,000 หรือ ๑๐๐๐</p>` : ''}</div>`;
}

function setActiveNumericField(index) {
    appState.activeFieldIndex = index;
    const input = document.querySelector(`#toolTopPanel input[data-shared-field="${index}"]`);
    if (input) input.dataset.visited = 'true';
    document.querySelectorAll('#toolTopPanel [data-field-index]').forEach(box => {
        const active = Number(box.dataset.fieldIndex) === index;
        box.classList.toggle(box.classList.contains('clev-field-box') ? 'active-field' : 'active-cell', active);
    });
}

function attachFieldClickListeners(container) {
    container.querySelectorAll('.shared-number-input').forEach(input => {
        const index = Number(input.dataset.sharedField);
        const binding = getToolFieldBindings(appState.activeToolId)[index];
        input.addEventListener('focus', () => setActiveNumericField(index));
        input.addEventListener('input', event => {
            const formatted = formatInputDisplay(input.value);
            if (binding) binding.set(formatted);
            persistAppState();
            if (!event.isComposing) renderActiveTool();
        });
        input.addEventListener('compositionend', () => renderActiveTool());
        input.addEventListener('keydown', event => {
            if (event.key === 'Backspace' && input.selectionStart === input.selectionEnd && input.selectionStart > 1) {
                if (input.value[input.selectionStart - 1] === ',') {
                    event.preventDefault();
                    const pos = input.selectionStart;
                    input.setRangeText('', pos - 2, pos, 'end');
                    input.dispatchEvent(new Event('input', { bubbles: true }));
                    return;
                }
            }
            if (event.key === 'Enter' && !event.isComposing) {
                event.preventDefault();
                input.blur();
            }
        });
        input.addEventListener('blur', () => {
            if (binding) {
                const formatted = formatInputDisplay(input.value);
                binding.set(formatted);
                input.value = formatted;
                persistAppState();
            }
        });
        input.closest('[data-field-index]').addEventListener('click', () => input.focus());
    });

}

(function(root) {
    const exportsObj = {
        getToolFieldBindings,
        handleSharedKeyInput,
        updateKeypadCollapseUI,
        createKeypadFieldHTML,
        setActiveNumericField,
        attachFieldClickListeners
    };
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = exportsObj;
    }
    if (root) {
        Object.assign(root, exportsObj);
    }
})(typeof globalThis !== 'undefined' ? globalThis : typeof window !== 'undefined' ? window : this);

// <<< src/ui/keypad.js <<<

// >>> src/ui/charts.js >>>
// ==============================================================
// Multitools Calculator - Desktop Charts (Phase 8)
// Pure data helpers + SVG/HTML renderers. Colours come from the
// shared theme variables only. Panels are wrapped in the
// `desktop-chart hidden lg:block` shell so mobile never renders them.
// ==============================================================

const CHART_TONES = {
    accent: { color: 'var(--app-accent)', opacity: 1 },
    ink: { color: 'var(--app-ink)', opacity: 0.75 },
    muted: { color: 'var(--app-muted)', opacity: 0.55 },
    soft: { color: 'var(--app-surface-strong)', opacity: 1 }
};

// numberOrDefault returns NaN for invalid text; charts and what-if sliders want 0 instead.
function safeNumber(value, fallback = 0) {
    const n = numberOrDefault(value, fallback);
    return Number.isFinite(n) ? n : fallback;
}

function chartPercent(value, total) {
    return total > 0 ? (value / total) * 100 : 0;
}

/* ---------- pure data helpers (unit-tested) ---------- */

// Loan: split totals + a downsampled balance curve (max ~60 points).
function buildLoanChartData(schedule, maxPoints = 60) {
    const rows = Array.isArray(schedule) ? schedule : [];
    if (!rows.length) {
        return { totalPrincipal: 0, totalInterest: 0, totalPaid: 0, interestSharePct: 0, points: [] };
    }
    const totalPrincipal = rows.reduce((sum, r) => sum + r.principal, 0);
    const totalInterest = rows.reduce((sum, r) => sum + r.interest, 0);
    const totalPaid = totalPrincipal + totalInterest;
    const points = [{ month: 0, balance: rows[0].balance + rows[0].principal }];
    const step = Math.max(1, Math.ceil(rows.length / Math.max(2, maxPoints)));
    rows.forEach((r, i) => {
        if ((i + 1) % step === 0 || i === rows.length - 1) {
            points.push({ month: r.month, balance: r.balance });
        }
    });
    return {
        totalPrincipal,
        totalInterest,
        totalPaid,
        interestSharePct: chartPercent(totalInterest, totalPaid),
        points
    };
}

// Tax: waterfall steps from gross income down to net taxable income.
function buildTaxWaterfallSteps(calc) {
    if (!calc || !(calc.grossIncome > 0)) return [];
    const gross = calc.grossIncome;
    const steps = [{ label: 'เงินได้ทั้งปี', amount: gross, kind: 'total', start: 0, end: gross }];
    let running = gross;
    const pushMinus = (label, amount) => {
        const value = Math.max(0, Math.min(amount, running));
        if (value <= 0) return;
        steps.push({ label, amount: value, kind: 'minus', start: running - value, end: running });
        running -= value;
    };
    pushMinus('หักค่าใช้จ่าย', calc.expenses);
    pushMinus('ลดหย่อนส่วนตัว/ครอบครัว', calc.personalTotal);
    pushMinus('ลดหย่อนประกัน/ลงทุน', calc.savingsTotal);
    pushMinus('เงินบริจาค', calc.totalDonations);
    steps.push({ label: 'เงินได้สุทธิ', amount: running, kind: 'total', start: 0, end: running });
    return steps;
}

// Tax: where the net taxable income sits inside its bracket.
function buildTaxBracketGauge(calc) {
    if (!calc) return null;
    const start = calc.bracketStart || 0;
    const next = calc.nextBracketStart == null ? null : calc.nextBracketStart;
    const net = calc.netTaxableIncome || 0;
    const progress = next == null ? 1 : Math.min(1, Math.max(0, (net - start) / (next - start)));
    return {
        currentRatePercent: calc.marginalRate || 0,
        nextRatePercent: calc.nextRatePercent == null ? null : calc.nextRatePercent,
        amountToNext: next == null ? null : Math.max(0, next - net),
        progress
    };
}

// Salary: 50/30/20 split; leftover share (if percents < 100) is its own slice.
function buildSalarySplitData(params) {
    const p = params || {};
    const income = Math.max(0, safeNumber(p.income, 0));
    const needsPct = Math.max(0, safeNumber(p.needsPct, 0));
    const wantsPct = Math.max(0, safeNumber(p.wantsPct, 0));
    const savingsPct = Math.max(0, safeNumber(p.savingsPct, 0));
    const totalPct = needsPct + wantsPct + savingsPct;
    const slices = [
        { label: 'จำเป็น', pct: needsPct, amount: income * needsPct / 100, tone: 'accent' },
        { label: 'ไลฟ์สไตล์', pct: wantsPct, amount: income * wantsPct / 100, tone: 'ink' },
        { label: 'ออม/ลงทุน', pct: savingsPct, amount: income * savingsPct / 100, tone: 'muted' }
    ];
    if (totalPct < 100) {
        slices.push({ label: 'ยังไม่ได้จัดสรร', pct: 100 - totalPct, amount: income * (100 - totalPct) / 100, tone: 'soft' });
    }
    return { income, totalPct, overAllocated: totalPct > 100, slices };
}

/* ---------- renderers ---------- */

function chartToneStyle(tone) {
    const t = CHART_TONES[tone] || CHART_TONES.muted;
    return `color:${t.color};opacity:${t.opacity}`;
}

function renderChartLegend(items) {
    return `<ul class="chart-legend space-y-1 text-xs">${items.map(item => `
        <li class="flex items-center justify-between gap-2">
            <span class="flex items-center gap-1.5 min-w-0">
                <span class="inline-block w-2.5 h-2.5 rounded-sm shrink-0" style="background:currentColor;${chartToneStyle(item.tone)}" aria-hidden="true"></span>
                <span class="truncate text-[var(--app-body)]">${escapeHTML(item.label)}</span>
            </span>
            <b class="text-[var(--app-ink)] whitespace-nowrap">${item.text}</b>
        </li>`).join('')}</ul>`;
}

// Donut (or pie when pie=true) built from stroked circles.
function renderDonutChart(slices, options = {}) {
    const visible = slices.filter(s => s.value > 0);
    const total = visible.reduce((sum, s) => sum + s.value, 0);
    if (total <= 0) return '';
    const pie = !!options.pie;
    const radius = pie ? 25 : 38;
    const stroke = pie ? 50 : 20;
    const circumference = 2 * Math.PI * radius;
    let offset = 0;
    const arcs = visible.map(s => {
        const length = (s.value / total) * circumference;
        // thin gap between neighbouring slices so they stay distinguishable when tones are close
        const gap = visible.length > 1 ? Math.min(1.2, length * 0.2) : 0;
        const drawn = length - gap;
        const arc = `<circle cx="60" cy="60" r="${radius}" fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-dasharray="${drawn.toFixed(3)} ${(circumference - drawn).toFixed(3)}" stroke-dashoffset="${(-offset).toFixed(3)}" transform="rotate(-90 60 60)" style="${chartToneStyle(s.tone)}"></circle>`;
        offset += length;
        return arc;
    }).join('');
    const center = !pie && options.centerText
        ? `<text x="60" y="58" text-anchor="middle" font-size="12" font-weight="700" fill="var(--app-ink)">${escapeHTML(options.centerText)}</text><text x="60" y="71" text-anchor="middle" font-size="7" fill="var(--app-muted)">${escapeHTML(options.centerSub || '')}</text>`
        : '';
    return `<svg viewBox="0 0 120 120" class="w-32 h-32 shrink-0" role="img" aria-label="${escapeHTML(options.ariaLabel || 'แผนภูมิสัดส่วน')}">${arcs}${center}</svg>`;
}

// Area/line chart of a value series (x = index, y = value).
function renderLineChart(points, options = {}) {
    if (!Array.isArray(points) || points.length < 2) return '';
    const secondary = Array.isArray(options.secondary) && options.secondary.length > 1 ? options.secondary : null;
    const width = 300, height = 110, padX = 4, padTop = 8, padBottom = 6;
    const maxY = Math.max(...points.map(p => p.balance), ...(secondary || []).map(p => p.balance), 1);
    const maxX = Math.max(points[points.length - 1].month, 1);
    const xy = p => [
        padX + (p.month / maxX) * (width - padX * 2),
        padTop + (1 - p.balance / maxY) * (height - padTop - padBottom)
    ];
    const toPath = list => list.map(xy).map(([x, y], i) => `${i ? 'L' : 'M'}${x.toFixed(1)} ${y.toFixed(1)}`).join(' ');
    const coords = points.map(xy);
    const line = toPath(points);
    const baseY = height - padBottom;
    const area = `${line} L${coords[coords.length - 1][0].toFixed(1)} ${baseY} L${coords[0][0].toFixed(1)} ${baseY} Z`;
    const second = secondary
        ? `<path d="${toPath(secondary)}" fill="none" stroke="var(--app-ink)" stroke-width="2" stroke-dasharray="5 4" stroke-linejoin="round" vector-effect="non-scaling-stroke"></path>`
        : '';
    return `<svg viewBox="0 0 ${width} ${height}" class="w-full h-auto" role="img" aria-label="${escapeHTML(options.ariaLabel || 'กราฟยอดคงเหลือ')}" preserveAspectRatio="none">
        <line x1="${padX}" y1="${baseY}" x2="${width - padX}" y2="${baseY}" stroke="var(--app-hairline)" stroke-width="1"></line>
        <path d="${area}" fill="var(--app-accent)" fill-opacity="0.14"></path>
        <path d="${line}" fill="none" stroke="var(--app-accent)" stroke-width="2" stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke"></path>
        ${second}
    </svg>`;
}

// Horizontal waterfall: one row per step, bar offset/width as % of gross.
function renderWaterfallChart(steps) {
    if (!steps.length) return '';
    const max = Math.max(...steps.map(s => s.end), 1);
    return `<div class="space-y-1.5" role="list">${steps.map(s => {
        const left = chartPercent(s.start, max);
        const width = Math.max(chartPercent(s.end - s.start, max), 0.8);
        const tone = s.kind === 'total' ? 'ink' : 'accent';
        return `<div role="listitem" class="text-[11px]">
            <div class="flex justify-between gap-2 text-[var(--app-body)]"><span>${escapeHTML(s.label)}</span><b class="text-[var(--app-ink)]">${s.kind === 'minus' ? '−' : ''}${formatMoney(s.amount)}</b></div>
            <div class="h-2 rounded-full relative overflow-hidden" style="box-shadow: inset 0 0 0 1px var(--app-hairline)"><span class="absolute top-0 bottom-0 rounded-full" style="left:${left.toFixed(2)}%;width:${width.toFixed(2)}%;background:currentColor;${chartToneStyle(tone)}"></span></div>
        </div>`;
    }).join('')}</div>`;
}

function renderChartPanel(title, bodyHTML) {
    return `<div class="desktop-chart themed-tool-card hidden lg:block p-4 space-y-3 text-xs" data-desktop-chart>
        <div class="font-bold text-[var(--app-ink)]">${escapeHTML(title)}</div>
        ${bodyHTML}
    </div>`;
}

function renderLoanChartPanel(schedule) {
    const data = buildLoanChartData(schedule);
    if (!data.points.length) return '';
    const donut = renderDonutChart([
        { value: data.totalPrincipal, tone: 'accent' },
        { value: data.totalInterest, tone: 'ink' }
    ], {
        centerText: `${data.interestSharePct.toFixed(1)}%`,
        centerSub: 'ดอกเบี้ย',
        ariaLabel: `เงินต้น ${formatMoney(data.totalPrincipal)} บาท ดอกเบี้ย ${formatMoney(data.totalInterest)} บาท`
    });
    const last = data.points[data.points.length - 1];
    return renderChartPanel('ภาพรวมสินเชื่อ', `
        <div class="flex items-center gap-4">
            ${donut}
            <div class="flex-1 min-w-0">${renderChartLegend([
                { label: 'เงินต้น', tone: 'accent', text: `${formatMoney(data.totalPrincipal)} ฿` },
                { label: 'ดอกเบี้ย', tone: 'ink', text: `${formatMoney(data.totalInterest)} ฿` },
                { label: 'รวมจ่ายทั้งหมด', tone: 'soft', text: `${formatMoney(data.totalPaid)} ฿` }
            ])}</div>
        </div>
        <div>
            <div class="font-semibold text-[var(--app-body)] mb-1">ยอดหนี้คงเหลือตลอดสัญญา</div>
            ${renderLineChart(data.points, { ariaLabel: `ยอดหนี้ลดจาก ${formatMoney(data.points[0].balance)} เหลือ ${formatMoney(last.balance)} บาท ใน ${last.month} งวด` })}
            <div class="flex justify-between text-[10px] text-[var(--app-body)] mt-0.5"><span>งวดที่ 0 · ${formatMoney(data.points[0].balance)}</span><span>งวดที่ ${last.month} · ${formatMoney(last.balance)}</span></div>
        </div>
        ${renderLoanWhatIfSection(schedule)}`);
}

function renderTaxChartPanel(calc, params) {
    const steps = buildTaxWaterfallSteps(calc);
    if (!steps.length) return '';
    const gauge = buildTaxBracketGauge(calc);
    const gaugeText = gauge.amountToNext == null
        ? `อยู่ในฐานภาษีสูงสุด ${gauge.currentRatePercent}%`
        : `ฐานภาษี ${gauge.currentRatePercent}% · อีก ${formatMoney(gauge.amountToNext)} บาท จะขึ้นฐาน ${gauge.nextRatePercent}%`;
    return renderChartPanel('จากเงินได้ถึงเงินได้สุทธิ', `
        ${renderWaterfallChart(steps)}
        <div class="space-y-1">
            <div class="font-semibold text-[var(--app-body)]">ระยะห่างถึงฐานภาษีถัดไป</div>
            <div class="h-2.5 rounded-full overflow-hidden" style="box-shadow: inset 0 0 0 1px var(--app-hairline)" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(gauge.progress * 100)}" aria-label="${escapeHTML(gaugeText)}"><div class="h-full rounded-full" style="width:${(gauge.progress * 100).toFixed(1)}%;background:var(--app-accent)"></div></div>
            <div class="text-[var(--app-body)]">${escapeHTML(gaugeText)}</div>
        </div>
        ${params ? renderTaxInsightsSection(params) : ''}`);
}

function renderSalaryChartPanel(params) {
    const data = buildSalarySplitData(params);
    if (data.income <= 0 || data.totalPct <= 0) return '';
    const pie = renderDonutChart(data.slices.map(s => ({ value: s.pct, tone: s.tone })), {
        pie: true,
        ariaLabel: data.slices.map(s => `${s.label} ${s.pct}%`).join(' ')
    });
    return renderChartPanel('สัดส่วนการจัดสรรเงินเดือน', `
        <div class="flex items-center gap-4">
            ${pie}
            <div class="flex-1 min-w-0">${renderChartLegend(data.slices.map(s => ({
                label: `${s.label} ${s.pct}%`,
                tone: s.tone,
                text: `${formatMoney(s.amount)} ฿`
            })))}</div>
        </div>
        ${data.overAllocated ? `<div class="text-[var(--app-body)]">สัดส่วนรวมเกิน 100% (${data.totalPct}%) กรุณาปรับให้ไม่เกินเงินเดือน</div>` : ''}
        ${renderSalaryWhatIfSection(params)}`);
}

// Car loan (flat rate): split of what is repaid, plus remaining balance with and without the early-payoff discount.
function buildCarLoanChartData(calc, rows) {
    if (!calc || !(calc.principal > 0) || !Array.isArray(rows) || !rows.length) return null;
    const total = calc.principal + calc.totalInterest + calc.totalVat;
    const points = [{ month: 0, balance: calc.totalRepayment }];
    const payoffPoints = [{ month: 0, balance: calc.totalRepayment }];
    rows.forEach(r => {
        points.push({ month: r.month, balance: r.fullRemaining });
        payoffPoints.push({ month: r.month, balance: r.payoffAmount });
    });
    return {
        principal: calc.principal,
        interest: calc.totalInterest,
        vat: calc.totalVat,
        totalRepayment: calc.totalRepayment,
        interestSharePct: chartPercent(calc.totalInterest, total),
        points,
        payoffPoints,
        maxSaved: Math.max(...rows.map(r => r.saved))
    };
}

function renderCarLoanChartPanel(calc, rows, params) {
    const data = buildCarLoanChartData(calc, rows);
    if (!data) return '';
    const slices = [
        { value: data.principal, tone: 'accent' },
        { value: data.interest, tone: 'ink' }
    ];
    const legend = [
        { label: 'เงินต้น (ยอดจัด)', tone: 'accent', text: `${formatMoney(data.principal)} ฿` },
        { label: 'ดอกเบี้ย', tone: 'ink', text: `${formatMoney(data.interest)} ฿` }
    ];
    if (data.vat > 0) {
        slices.push({ value: data.vat, tone: 'muted' });
        legend.push({ label: 'VAT 7% (รถมือสอง)', tone: 'muted', text: `${formatMoney(data.vat)} ฿` });
    }
    const donut = renderDonutChart(slices, {
        centerText: `${data.interestSharePct.toFixed(1)}%`,
        centerSub: 'ดอกเบี้ย',
        ariaLabel: `เงินต้น ${formatMoney(data.principal)} บาท ดอกเบี้ย ${formatMoney(data.interest)} บาท`
    });
    const last = data.points[data.points.length - 1];
    return renderChartPanel('ภาพรวมสินเชื่อรถ', `
        <div class="flex items-center gap-4">
            ${donut}
            <div class="flex-1 min-w-0">${renderChartLegend(legend)}</div>
        </div>
        <div>
            <div class="font-semibold text-[var(--app-body)] mb-1">ยอดคงเหลือตลอดสัญญา</div>
            ${renderLineChart(data.points, { secondary: data.payoffPoints, ariaLabel: `ยอดผ่อนคงเหลือลดจาก ${formatMoney(data.totalRepayment)} เหลือ ${formatMoney(last.balance)} บาท ใน ${last.month} งวด เส้นประคือยอดปิดบัญชีหลังส่วนลด สคบ.` })}
            <div class="flex justify-between text-[10px] text-[var(--app-body)] mt-0.5"><span>งวดที่ 0 · ${formatMoney(data.totalRepayment)}</span><span>งวดที่ ${last.month} · ${formatMoney(last.balance)}</span></div>
            <ul class="chart-legend text-[11px] text-[var(--app-body)] mt-1 space-y-0.5">
                <li>เส้นทึบ: ยอดผ่อนคงเหลือตามสัญญา</li>
                <li>เส้นประ: ยอดปิดบัญชีหลังส่วนลด สคบ. (ประหยัดสูงสุด ${formatMoney(data.maxSaved)} ฿)</li>
            </ul>
        </div>
        ${params ? renderCarLoanWhatIfSection(params) : ''}`);
}

// <<< src/ui/charts.js <<<

// >>> src/ui/whatif.js >>>
// ==============================================================
// Multitools Calculator - What-If Sliders & Smart Insights (Phase 8)
// Desktop-only sections that live inside the chart panels
// (src/ui/charts.js). Sliders never re-render the tool: one delegated
// listener updates the delta text in place from the current appState.
// ==============================================================

/* ---------- pure engines (unit-tested) ---------- */

// Loan: effect of paying `extraDelta` more per month on top of the current plan.
function computeLoanWhatIf(params, extraDelta) {
    const p = params || {};
    const delta = Math.max(0, safeNumber(extraDelta, 0));
    const sum = rows => rows.reduce((total, r) => total + r.interest, 0);
    const base = generateLoanSchedule(p);
    const alt = generateLoanSchedule({ ...p, extra: Math.max(0, safeNumber(p.extra, 0)) + delta });
    const baseInterest = sum(base);
    const newInterest = sum(alt);
    return {
        baseMonths: base.length,
        newMonths: alt.length,
        baseInterest,
        newInterest,
        interestSaved: Math.max(0, baseInterest - newInterest),
        monthsSaved: Math.max(0, base.length - alt.length)
    };
}

// Salary: move `shiftPct` of income from lifestyle spending into savings.
function computeSalaryWhatIf(params, shiftPct) {
    const p = params || {};
    const income = Math.max(0, safeNumber(p.income, 0));
    const wantsPct = Math.max(0, safeNumber(p.wantsPct, 0));
    const savingsPct = Math.max(0, safeNumber(p.savingsPct, 0));
    const shift = Math.min(wantsPct, Math.max(0, safeNumber(shiftPct, 0)));
    const extraMonthly = income * shift / 100;
    return {
        shift,
        newWantsPct: wantsPct - shift,
        newSavingsPct: savingsPct + shift,
        extraMonthly,
        extraYearly: extraMonthly * 12
    };
}

// Tax: effect of putting `amount` more into one deductible fund (key = param name).
function computeTaxWhatIf(params, key, amount) {
    const p = params || {};
    const add = Math.max(0, safeNumber(amount, 0));
    const base = calculatePersonalTax(p);
    const alt = calculatePersonalTax({ ...p, [key]: Math.max(0, safeNumber(p[key], 0)) + add });
    return {
        baseTax: base.totalTax,
        newTax: alt.totalTax,
        taxSaved: Math.max(0, base.totalTax - alt.totalTax),
        newNetTaxable: alt.netTaxableIncome
    };
}

// Tax: remaining deduction quota per fund and the refund it would unlock.
function computeTaxInsights(params) {
    const p = params || {};
    const base = calculatePersonalTax(p);
    const gross = base.grossIncome;
    const used = key => Math.max(0, safeNumber(p[key], 0));
    const retirementLeft = Math.max(0, 500000 - base.details.retirementCombo);
    const funds = [
        { key: 'ssf', label: 'SSF', cap: Math.min(200000, gross * 0.30), shared: true },
        { key: 'rmf', label: 'RMF', cap: Math.min(500000, gross * 0.30), shared: true },
        { key: 'thaiEsg', label: 'Thai ESG', cap: Math.min(300000, gross * 0.30), shared: false }
    ];
    return funds.map(fund => {
        let remaining = Math.max(0, fund.cap - used(fund.key));
        if (fund.shared) remaining = Math.min(remaining, retirementLeft);
        remaining = Math.floor(remaining);
        const cashBack = remaining > 0 ? computeTaxWhatIf(p, fund.key, remaining).taxSaved : 0;
        return { key: fund.key, label: fund.label, remaining, cashBack };
    });
}

// Car loan: effect of putting `extraDown` baht more into the down payment.
function computeCarLoanWhatIf(params, extraDown) {
    const p = params || {};
    const base = calculateCarLoan(p);
    const extra = Math.max(0, safeNumber(extraDown, 0));
    const alt = calculateCarLoan({ ...p, downPaymentType: 'amount', downPaymentValue: Math.min(base.price, base.downPaymentAmount + extra) });
    return {
        extraDown: Math.min(extra, Math.max(0, base.price - base.downPaymentAmount)),
        baseMonthly: base.monthlyPayment,
        newMonthly: alt.monthlyPayment,
        monthlySaved: Math.max(0, base.monthlyPayment - alt.monthlyPayment),
        interestSaved: Math.max(0, base.totalInterest - alt.totalInterest),
        newPrincipal: alt.principal,
        newTotalRepayment: alt.totalRepayment
    };
}

// Air conditioners = items with an "air..." id or an air-con name.
function isAirConditionerItem(item) {
    const it = item || {};
    return /^air/i.test(String(it.id || '')) || /แอร์|เครื่องปรับอากาศ|air\s*con/i.test(String(it.name || ''));
}

// Appliances: cut `reduceHours` per day off every air conditioner (never below 0).
function computeApplianceWhatIf(appliances, unitCost, reduceHours) {
    const list = Array.isArray(appliances) ? appliances : [];
    const rate = Math.max(0, safeNumber(unitCost, 4.5));
    const cut = Math.max(0, safeNumber(reduceHours, 0));
    const base = calculateApplianceEnergy(list, rate);
    const alt = calculateApplianceEnergy(list.map(item => (isAirConditionerItem(item)
        ? { ...item, hoursPerDay: Math.max(0, safeNumber(item.hoursPerDay, 0) - cut) }
        : item)), rate);
    const acItems = list.filter(isAirConditionerItem);
    return {
        acCount: acItems.length,
        maxHours: Math.max(0, ...acItems.map(item => safeNumber(item.hoursPerDay, 0))),
        savedKwh: Math.max(0, base.totalMonthlyKwh - alt.totalMonthlyKwh),
        savedBaht: Math.max(0, base.totalMonthlyCost - alt.totalMonthlyCost),
        savedBahtYearly: Math.max(0, base.totalMonthlyCost - alt.totalMonthlyCost) * 12,
        newMonthlyCost: alt.totalMonthlyCost
    };
}

/* ---------- section renderers ---------- */

function whatIfSection(kind, title, bodyHTML, attrs = '') {
    return `<div class="border-t border-[var(--app-hairline)] pt-3 space-y-2" data-whatif="${kind}" ${attrs}>
        <div class="font-bold text-[var(--app-ink)]">${escapeHTML(title)}</div>
        ${bodyHTML}
    </div>`;
}

function whatIfRow(label, outKey, initialText) {
    return `<div class="flex justify-between gap-2"><span class="text-[var(--app-body)]">${escapeHTML(label)}</span><b class="text-[var(--app-ink)] text-right" data-out="${outKey}">${initialText}</b></div>`;
}

function whatIfRange(id, label, min, max, step) {
    return `<label for="${id}" class="flex justify-between gap-2 font-semibold text-[var(--app-body)]"><span>${escapeHTML(label)}</span><span data-out="slider" class="text-[var(--app-ink)]">0</span></label>
        <input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="0" class="w-full" style="accent-color: var(--app-accent)">`;
}

function renderLoanWhatIfSection(schedule) {
    if (!Array.isArray(schedule) || !schedule.length) return '';
    const max = Math.max(2000, Math.ceil(schedule[0].payment / 500) * 500);
    return whatIfSection('loan', 'ลองโปะเพิ่มต่อเดือน', `
        ${whatIfRange('whatifLoanExtra', 'โปะเพิ่ม (บาท/เดือน)', 0, max, 500)}
        ${whatIfRow('ดอกเบี้ยที่ประหยัดได้', 'interestSaved', '0.00 ฿')}
        ${whatIfRow('ลดระยะเวลาผ่อน', 'monthsSaved', '0 งวด')}
        ${whatIfRow('ผ่อนเสร็จใน', 'newMonths', `${schedule.length} งวด`)}`);
}

function renderSalaryWhatIfSection(params) {
    const p = params || {};
    const income = safeNumber(p.income, 0);
    const wantsPct = safeNumber(p.wantsPct, 0);
    if (income <= 0 || wantsPct <= 0) return '';
    return whatIfSection('salary', 'ลองลดไลฟ์สไตล์เพื่อออมเพิ่ม', `
        ${whatIfRange('whatifSalaryShift', 'ย้ายจากไลฟ์สไตล์ไปออม (% ของเงินเดือน)', 0, Math.floor(wantsPct), 1)}
        ${whatIfRow('ออมเพิ่มต่อเดือน', 'extraMonthly', '0.00 ฿')}
        ${whatIfRow('ออมเพิ่มต่อปี', 'extraYearly', '0.00 ฿')}
        ${whatIfRow('สัดส่วนใหม่ ไลฟ์สไตล์ / ออม', 'split', `${wantsPct}% / ${safeNumber(p.savingsPct, 0)}%`)}`);
}

function renderTaxInsightsSection(params) {
    const insights = computeTaxInsights(params);
    const open = insights.filter(i => i.remaining > 0);
    if (!open.length) {
        return whatIfSection('tax-none', 'สิทธิ์ลดหย่อนที่เหลือ', `<div class="text-[var(--app-body)]">ใช้สิทธิ์ลดหย่อน SSF, RMF และ Thai ESG ครบตามเพดานแล้ว</div>`);
    }
    const rows = insights.map(i => `<div class="flex justify-between gap-2"><span class="text-[var(--app-body)]">${i.label} เหลือสิทธิ์ ${formatMoney(i.remaining)} ฿</span><b class="text-[var(--app-ink)] whitespace-nowrap">คืนภาษี ~${formatMoney(i.cashBack)} ฿</b></div>`).join('');
    const first = open[0];
    const stepFor = r => (r >= 1000 ? 1000 : 1);
    const maxFor = r => (r >= 1000 ? Math.floor(r / 1000) * 1000 : r);
    return whatIfSection('tax', 'สิทธิ์ลดหย่อนที่เหลือ และลองซื้อเพิ่ม', `
        <div class="space-y-1">${rows}</div>
        <label for="whatifTaxFund" class="font-semibold text-[var(--app-body)] block">เลือกกองทุนที่จะลองซื้อเพิ่ม</label>
        <select id="whatifTaxFund" class="airbnb-input w-full text-xs" data-whatif-fund>${open.map(i => `<option value="${i.key}">${i.label}</option>`).join('')}</select>
        ${whatIfRange('whatifTaxAmount', 'ซื้อเพิ่ม (บาท)', 0, maxFor(first.remaining), stepFor(first.remaining))}
        ${whatIfRow('ภาษีที่ประหยัดได้', 'taxSaved', '0.00 ฿')}
        ${whatIfRow('ภาษีทั้งปีหลังซื้อเพิ่ม', 'newTax', `${formatMoney(computeTaxWhatIf(params, first.key, 0).baseTax)} ฿`)}`,
        `data-quotas="${escapeHTML(JSON.stringify(open.map(i => ({ key: i.key, remaining: i.remaining }))))}"`);
}

function renderCarLoanWhatIfSection(params) {
    const base = calculateCarLoan(params || {});
    const max = Math.floor(Math.min(base.principal, base.price * 0.3) / 5000) * 5000;
    if (!(base.principal > 0) || max < 5000) return '';
    return whatIfSection('car', 'ลองเพิ่มเงินดาวน์', `
        ${whatIfRange('whatifCarDown', 'ดาวน์เพิ่ม (บาท)', 0, max, 5000)}
        ${whatIfRow('ค่างวดลดลง', 'monthlySaved', '0.00 ฿/เดือน')}
        ${whatIfRow('ดอกเบี้ยที่ประหยัดได้', 'interestSaved', '0.00 ฿')}
        ${whatIfRow('ค่างวดใหม่', 'newMonthly', `${formatMoney(base.monthlyPayment)} ฿/เดือน`)}`);
}

function renderApplianceWhatIfSection(appliances, unitCost) {
    const info = computeApplianceWhatIf(appliances, unitCost, 0);
    if (!info.acCount || !(info.maxHours > 0)) return '';
    return whatIfSection('ac', 'ลองลดชั่วโมงเปิดแอร์', `
        ${whatIfRange('whatifAcHours', 'ลดเวลาเปิดแอร์ (ชั่วโมง/วัน)', 0, Math.floor(info.maxHours * 2) / 2, 0.5)}
        ${whatIfRow('ประหยัดค่าไฟต่อเดือน', 'savedBaht', '0.00 ฿')}
        ${whatIfRow('ประหยัดค่าไฟต่อปี', 'savedBahtYearly', '0.00 ฿')}
        ${whatIfRow('ใช้ไฟลดลง', 'savedKwh', '0.0 หน่วย/เดือน')}`);
}

/* ---------- live updates (one delegated listener, no re-render) ---------- */

function updateWhatIfSection(section, resetSlider) {
    const kind = section.dataset.whatif;
    const range = section.querySelector('input[type="range"]');
    if (!range) return;
    const set = (key, text) => {
        const el = section.querySelector(`[data-out="${key}"]`);
        if (el) el.textContent = text;
    };
    if (kind === 'tax') {
        const fund = section.querySelector('[data-whatif-fund]')?.value;
        if (resetSlider) {
            let quotas = [];
            try { quotas = JSON.parse(section.dataset.quotas || '[]'); } catch (e) { quotas = []; }
            const remaining = quotas.find(q => q.key === fund)?.remaining || 0;
            range.max = remaining >= 1000 ? Math.floor(remaining / 1000) * 1000 : remaining;
            range.step = remaining >= 1000 ? 1000 : 1;
            range.value = 0;
        }
    }
    const value = safeNumber(range.value, 0);
    if (kind === 'loan') {
        const r = computeLoanWhatIf(appState.loan, value);
        set('slider', `${formatMoney(value)} ฿`);
        set('interestSaved', `${formatMoney(r.interestSaved)} ฿`);
        set('monthsSaved', `${r.monthsSaved} งวด`);
        set('newMonths', `${r.newMonths} งวด`);
    } else if (kind === 'salary') {
        const st = appState.salary;
        const r = computeSalaryWhatIf({ income: st.income, wantsPct: st.wantsPct, savingsPct: st.savingsPct }, value);
        set('slider', `${r.shift}%`);
        set('extraMonthly', `${formatMoney(r.extraMonthly)} ฿`);
        set('extraYearly', `${formatMoney(r.extraYearly)} ฿`);
        set('split', `${r.newWantsPct}% / ${r.newSavingsPct}%`);
    } else if (kind === 'car') {
        const r = computeCarLoanWhatIf(appState.car_loan, value);
        set('slider', `${formatMoney(value)} ฿`);
        set('monthlySaved', `${formatMoney(r.monthlySaved)} ฿/เดือน`);
        set('interestSaved', `${formatMoney(r.interestSaved)} ฿`);
        set('newMonthly', `${formatMoney(r.newMonthly)} ฿/เดือน`);
    } else if (kind === 'ac') {
        const st = appState.electricity_bill;
        const rate = calculateElectricityBill(st).avgRatePerUnit || 4.5;
        const r = computeApplianceWhatIf(st.appliances, rate, value);
        set('slider', `${value} ชม./วัน`);
        set('savedBaht', `${formatMoney(r.savedBaht)} ฿`);
        set('savedBahtYearly', `${formatMoney(r.savedBahtYearly)} ฿`);
        set('savedKwh', `${r.savedKwh.toFixed(1)} หน่วย/เดือน`);
    } else if (kind === 'tax') {
        const fund = section.querySelector('[data-whatif-fund]')?.value;
        const r = computeTaxWhatIf(appState.tax_personal, fund, value);
        set('slider', `${formatMoney(value)} ฿`);
        set('taxSaved', `${formatMoney(r.taxSaved)} ฿`);
        set('newTax', `${formatMoney(r.newTax)} ฿`);
    }
}

function handleWhatIfEvent(event) {
    const section = event.target?.closest?.('[data-whatif]');
    if (!section) return;
    updateWhatIfSection(section, event.type === 'change' && event.target.matches('[data-whatif-fund]'));
}

if (typeof document !== 'undefined' && typeof document.addEventListener === 'function' && !globalThis.__whatIfBound) {
    globalThis.__whatIfBound = true;
    document.addEventListener('input', handleWhatIfEvent);
    document.addEventListener('change', handleWhatIfEvent);
}

